def main():
 items=[]
 for source, raw in SEED.items():
  for line in raw.strip().splitlines():
   if not line.strip(): continue
   number,title,text,sanction,tags = line.strip().split('|')
   entry={'id':f'{source}-{number}','source':source,'number':number,'title':title,'summary':text,'text':text + ((' '+sanction) if sanction else ''),'sanction':sanction,'tags':tags,'chapter':'','verified':'2026-10-15'}
   if source == 'koap' and number in SAY_PHRASES:
    entry['say'] = SAY_PHRASES[number]
    entry['text'] = FULL_TEXT[number]
   items.append(entry)
 result={'schema':1,'mode':'starter','updatedAt':'2026-10-15','sources':SOURCES,'items':items}
 target=Path(__file__).resolve().parents[1]/'data'/'laws.json'
 target.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 (target.parent/'laws.js').write_text('window.PROVINCE_LAWS = '+json.dumps(result,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
 print('Created',len(items),'starter records:', target)

if __name__=='__main__': main()
